119 | 
120 |     if (isEditing && customer) {
121 |       // UPDATE: optimistic patch table NGAY (apply). Đóng modal SAU khi action hoàn tất
122 |       // để tránh race condition khi user mở modal khác ngay (isSubmitting=true kẹt).
123 |       const id = customer.id;
124 |       payload.expectedUpdatedAt = customer.updated_at || undefined;
