148 |                 : cur;
149 |             }),
150 |           rollback: () => onSaved?.(),
151 |           action: () => updateCustomer(id, payload),
152 |           onSuccess: () => {
153 |             // optimistic update đã apply; onSaved/onClose chạy sau khi await resolve
154 |           },
155 |           onError: (err) => {
156 |             if (err instanceof Error) toast.error(err.message || "Đã xảy ra lỗi khi lưu khách hàng");
157 |           },
158 |         });
159 |         onSaved?.();
160 |         onClose();
